/** Deterministic pause/resume checks using generated bytes and preverified
 * numerical cache fixtures. No real replay, network, or production writes. */
import assert from "node:assert/strict";
import { promises as filesystem } from "node:fs";
import { mkdtemp, mkdir, writeFile, readFile, stat, rm, unlink } from "node:fs/promises";
import { syncBuiltinESMExports } from "node:module";
import path from "node:path";
import { tmpdir } from "node:os";
import { mock } from "node:test";
import { gzipSync } from "node:zlib";
import { buildRankedBaselines, rankedBuildIdentity } from "./build-ranked-baselines.mjs";
import { ACTIONS } from "./lib/ranked-aggregation.mjs";
import { sha256 } from "./lib/ranked-source-stream.mjs";
import { REPOSITORY, REVISION } from "./ranked-source-pilot.mjs";

const cache = await mkdtemp(path.join(tmpdir(), "ssbm-ranked-pause-checks-"));
const { parserFingerprint } = await rankedBuildIdentity();
const parsedDirectory = path.join(cache, "parsed", parserFingerprint), controlFile = path.join(cache, "ranked-job-control.json");
await mkdir(parsedDirectory, { recursive: true }); await mkdir(path.join(cache, "archives"), { recursive: true });
const writeJson = (file, value) => writeFile(file, JSON.stringify(value) + "\n");
const exists = async file => Boolean(await stat(file).catch(() => null));
const side = characterId => ({ characterId, totalDamage: 20, neutralWins: 1, openingsPerKill: 2, damagePerOpening: 20, inputsPerMinute: 250,
  lCancelSuccess: 1, lCancelFail: 0, techs: { inPlace: 0, toward: 0, away: 0, missed: 0, wallSuccess: 0, wallMissed: 0 },
  actions: Object.fromEntries(ACTIONS.map(action => [action, 0])), moveStats: {} });
function tarMember(name, bytes) {
  const header = Buffer.alloc(512); header.write(name); header.write(bytes.length.toString(8).padStart(11, "0") + "\0", 124); header.fill(32, 148, 156); header.write("0", 156);
  const sum = header.reduce((count, byte) => count + byte, 0); header.write(sum.toString(8).padStart(6, "0") + "\0 ", 148);
  return Buffer.concat([header, bytes, Buffer.alloc((512 - bytes.length % 512) % 512)]);
}
const files = [], hashes = [];
for (const [directory, count] of [["FOX", 2], ["FALCO", 6]]) {
  const members = [];
  for (let i = 0; i < count; i++) {
    const bytes = Buffer.from(`Synthetic replay-byte cache fixture ${directory} ${i}`), hash = sha256(bytes); hashes.push(hash);
    const result = { sha256: hash, bytes: bytes.length, rawCommandSha256: sha256(`raw ${directory} ${i}`), tiers: ["diamond", "master"], playerIndexes: [0, 1],
      frameCount: 3724, lastFrame: 3600, endMethod: 2, reasons: [], record: { statsVersion: 10, durationFrames: 3600, stageId: 31, isTeams: false, winnerIndex: i % 2, players: [side(20), side(2)] } };
    await writeJson(path.join(parsedDirectory, `${hash}.json`), { parserFingerprint, result });
    members.push(tarMember(`master-diamond-fixture-${i}.slp`, bytes));
  }
  const archive = gzipSync(Buffer.concat([...members, Buffer.alloc(1024)])), hash = sha256(archive);
  files.push({ path: `${directory}/${directory}_master-diamond_a1.tar.gz`, bytes: archive.length, sha256: hash });
  await writeFile(path.join(cache, "archives", `${hash}.tar.gz`), archive);
}
assert.ok(files[0].bytes < files[1].bytes);
const sourceManifest = path.join(cache, "source-manifest.json");
await writeJson(sourceManifest, { repository: REPOSITORY, revision: REVISION, selectionMethod: "Generated cache fixtures for pause/resume tests only.", files });
const output = path.join(cache, "staged"), datasetId = "ranked-pause-fixture-v1";
const options = { sourceManifest, cache, datasetId, output, workers: 1, download: false, waitDownloads: false };
// The tiny generated fixture must not depend on runner disk capacity. This
// process-local observation leaves the production builder's 8GiB guard intact;
// verify-ranked-export-quality exercises its low-space rejection separately.
const storageStats = mock.method(filesystem, "statfs", async directory => {
  assert.equal(directory, cache); return { bavail: 16 * 1024 ** 3, bsize: 1 };
});
syncBuiltinESMExports();
try {
  await writeJson(controlFile, { pauseRequested: false });
  // One deliberately invalid synthetic replay has no prior inspection. Pause
  // while its real worker is in flight: the rejection inspection must still
  // reach the atomic cache before the worker pool closes.
  const drainingFile = path.join(parsedDirectory, `${hashes[0]}.json`), drainingFixture = await readFile(drainingFile);
  await unlink(drainingFile);
  let observedPending = false;
  const drained = await buildRankedBaselines({ ...options, workers: 2, onProgress: async progress => {
    if (!observedPending && progress.pending > 0) {
      observedPending = true; await writeJson(controlFile, { pauseRequested: true, reason: "in-flight worker drain test" });
    }
  } });
  assert.equal(observedPending, true); assert.equal(drained.status, "paused"); assert.equal(drained.pending, 0); assert.equal(drained.parsed, 1);
  assert.equal(drained.archivesFinished, 0);
  const persistedRejection = JSON.parse(await readFile(drainingFile));
  assert.equal(persistedRejection.result.sha256, hashes[0]); assert.ok(persistedRejection.result.reasons.length > 0);
  assert.equal(await exists(output), false);
  await writeFile(drainingFile, drainingFixture); await writeJson(controlFile, { pauseRequested: false });
  const first = await buildRankedBaselines({ ...options, pauseAfterArchives: 1 });
  assert.equal(first.status, "paused"); assert.equal(first.reason, "archive-batch-limit"); assert.equal(first.pending, 0);
  assert.equal(first.archivesCompletedThisRun, 1); assert.equal(first.resumeArchiveSkips, 0); assert.equal(first.archivesFinished, 1);
  assert.equal(first.completedSourceBytes, files[0].bytes); assert.equal(first.totalSourceBytes, files[0].bytes + files[1].bytes);
  assert.equal(first.parsed, 0); assert.equal(first.reused, 2); assert.equal(await exists(output), false, "batch pause cannot create a partial export");
  let requested = false;
  const partial = await buildRankedBaselines({ ...options, onProgress: async progress => {
    if (!requested && progress.status === "running" && progress.resumeArchiveSkips === 1 && progress.replayOccurrences === 3) {
      requested = true; await writeJson(controlFile, { pauseRequested: true, reason: "synthetic mid-archive pause" });
    }
  } });
  assert.equal(requested, true); assert.equal(partial.status, "paused"); assert.equal(partial.reason, "control-request");
  assert.equal(partial.pending, 0); assert.equal(partial.resumeArchiveSkips, 1); assert.equal(partial.archivesFinished, 1); assert.equal(partial.reused, 3);
  assert.equal(partial.archivesCompletedThisRun, 0); assert.equal(await exists(output), false);
  assert.equal(await exists(path.join(cache, "members", `${files[1].sha256}.local.json`)), false, "partial archive never receives a complete member receipt");
  const stillPaused = await buildRankedBaselines(options);
  assert.equal(stillPaused.status, "paused"); assert.equal(stillPaused.replayOccurrences, 0, "resume requires the shared flag to be cleared");
  await writeJson(controlFile, { pauseRequested: false });
  const resumed = await buildRankedBaselines(options);
  assert.equal(resumed.status, "complete"); assert.equal(resumed.parsed, 0); assert.equal(resumed.reused, 8, "partial work cache is reused without reparsing");
  assert.equal(resumed.resumeArchiveSkips, 1); assert.equal(resumed.archivesCompletedThisRun, 1); assert.equal(resumed.counts.acceptedGames, 8);
  assert.equal(await exists(path.join(output, "manifest.json")), true);
  const progress = JSON.parse(await readFile(path.join(cache, `${datasetId}.progress.local.json`)));
  assert.equal(progress.status, "complete"); assert.equal(progress.completedSourceBytes, progress.totalSourceBytes);
  const allCached = await buildRankedBaselines({ ...options, datasetId: "ranked-pause-fixture-v2", output: path.join(cache, "staged-2"), pauseAfterArchives: 1 });
  assert.equal(allCached.status, "complete", "already-complete receipts do not consume a new-archive pause budget");
  assert.equal(allCached.resumeArchiveSkips, 2); assert.equal(allCached.archivesCompletedThisRun, 0); assert.equal(allCached.parsed, 0); assert.equal(allCached.reused, 8);
  const corruptFile = path.join(parsedDirectory, `${hashes[0]}.json`), original = await readFile(corruptFile), corrupt = JSON.parse(original);
  corrupt.result.sha256 = "0".repeat(64); await writeJson(corruptFile, corrupt);
  await assert.rejects(buildRankedBaselines({ ...options, datasetId: "ranked-pause-corrupt", output: path.join(cache, "invalid-output") }), /Expected values/);
  assert.equal(await exists(path.join(cache, "invalid-output")), false, "receipt resume validates each cache identity before export");
  await writeFile(corruptFile, original);
  assert.equal((await rankedBuildIdentity()).parserFingerprint, parserFingerprint, "pause control changes do not invalidate replay statistics");
} finally {
  storageStats.mock.restore(); syncBuiltinESMExports();
  const resolved = path.resolve(cache); assert.equal(path.dirname(resolved), path.resolve(tmpdir())); assert.ok(path.basename(resolved).startsWith("ssbm-ranked-pause-checks-"));
  await rm(resolved, { recursive: true });
}
console.log("Ranked pause/resume passed: drained batch and mid-archive pause, persistent control, no partial export, preserved cache, complete-receipt decompression skips, cache identity checks, and exact source-volume progress.");
